// Generates the TypeScript API types from openapi.json, which the daemon build writes.
// Usage: node scripts/generate.ts           writes src/generated/
//        imported by tools/checks/repo-check.ts to detect stale generated files.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
export const openapiPath = join(packageRoot, 'openapi.json');
export const generatedDirectory = join(packageRoot, 'src', 'generated');

const HEADER =
  '// Generated by packages/api-client/scripts/generate.ts from openapi.json. Do not edit.\n\n';

interface OpenApiDocument {
  components?: { schemas?: Record<string, { enum?: unknown[]; 'x-enum-varnames'?: string[] }> };
}

/** Returns the generated files as a map from file name to content. */
export async function generate(): Promise<Map<string, string>> {
  const source = readFileSync(openapiPath, 'utf8');
  const document = JSON.parse(source) as OpenApiDocument;

  const ast = await openapiTS(source, { alphabetize: true, exportType: true });
  const schema = HEADER + astToString(ast);

  const codes = (document.components?.schemas?.ErrorCode?.enum ?? []).map(String).sort();
  const errorCodes =
    HEADER +
    `export const errorCodes = [\n${codes.map((code) => `  '${code}',\n`).join('')}] as const;\n\n` +
    'export type ErrorCode = (typeof errorCodes)[number];\n';

  const closeCodeSchema = document.components?.schemas?.WebSocketCloseCode;
  const closeCodeNames = closeCodeSchema?.['x-enum-varnames'] ?? [];
  const closeCodes =
    HEADER +
    '/** Close codes the daemon sends on /ws, by name. */\n' +
    `export const closeCodes = {\n${closeCodeNames.map((name, index) => `  ${name}: ${String(closeCodeSchema?.enum?.[index])},\n`).join('')}} as const;\n\n` +
    'export type CloseCodeName = keyof typeof closeCodes;\n';

  return new Map([
    ['schema.ts', schema],
    ['error-codes.ts', errorCodes],
    ['close-codes.ts', closeCodes],
  ]);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  for (const [name, content] of await generate()) {
    writeFileSync(join(generatedDirectory, name), content);
  }
}
